import math
AV = {"N": 0.85, "A": 0.62, "L": 0.55, "P": 0.2}
AC = {"L": 0.77, "H": 0.44}
PR = {"N": 0.85, "L": 0.62, "H": 0.27}    # values for scope unchanged
UI = {"N": 0.85, "R": 0.62}
CIA = {"H": 0.56, "L": 0.22, "N": 0.0}

def roundup(x):                    # CVSS v3.1 Appendix A
    i = round(x * 100000)
    if i % 10000 == 0:
        return i / 100000.0
    return (math.floor(i / 10000) + 1) / 10.0

def base_score(vector):            # handles scope unchanged (S:U) only
    m = dict(p.split(":") for p in vector.split("/")[1:])
    iss = 1 - (1 - CIA[m["C"]]) * (1 - CIA[m["I"]]) * (1 - CIA[m["A"]])
    impact = 6.42 * iss
    expl = 8.22 * AV[m["AV"]] * AC[m["AC"]] * PR[m["PR"]] * UI[m["UI"]]
    if impact <= 0:
        return 0.0
    return roundup(min(impact + expl, 10))

v = "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"
print(base_score(v))

FIXED = {(2, 3): (2, 3, 32), (2, 5): (2, 5, 10, 1)}

def parse(v):
    return tuple(int(x) for x in v.split("."))

def vulnerable(version):
    v = parse(version)
    fixed = FIXED.get(v[:2])
    if fixed is None:
        return None          # this advisory does not cover that branch
    return v < fixed

